import{_ as s,o as a,c as t,a3 as o}from"./chunks/framework.DH50UWNB.js";const u=JSON.parse(`{"title":"Concepts","description":"The words Wake's docs use, explained: project, phase, task, claim, session, evidence, milestone and version.","frontmatter":{"description":"The words Wake's docs use, explained: project, phase, task, claim, session, evidence, milestone and version."},"headers":[],"relativePath":"start/concepts.md","filePath":"start/concepts.md","lastUpdated":1794486787000}`),n={name:"start/concepts.md"};function i(r,e,h,c,d,l){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="concepts" tabindex="-1">Concepts <a class="header-anchor" href="#concepts" aria-label="Permalink to &quot;Concepts&quot;">​</a></h1><p>The words the rest of these docs use. Each one is something you see in the web app or write in your plan.</p><h2 id="project" tabindex="-1">Project <a class="header-anchor" href="#project" aria-label="Permalink to &quot;Project&quot;">​</a></h2><p>A project is one repository that Wake follows. <code>wake setup</code> creates it, named after the repository&#39;s folder, in a workspace: your personal one, or one you share with other people (see <a href="/wake-dist/docs/use/workspaces">Workspaces and roles</a>). Its plan comes from the repository, and each sync brings Wake up to date with it.</p><h2 id="phase" tabindex="-1">Phase <a class="header-anchor" href="#phase" aria-label="Permalink to &quot;Phase&quot;">​</a></h2><p>A phase is one part of the plan, with its own list of tasks. What counts as a phase depends on how you plan: an <a href="/wake-dist/docs/agents/openspec">OpenSpec</a> change, a <a href="/wake-dist/docs/agents/spec-kit">Spec Kit</a> feature or an <a href="/wake-dist/docs/agents/odd">ODD</a> feature document. The <strong>Roadmap</strong> shows your phases in order.</p><h2 id="task" tabindex="-1">Task <a class="header-anchor" href="#task" aria-label="Permalink to &quot;Task&quot;">​</a></h2><p>A task is one item of a phase&#39;s task list, such as a checkbox line. It may depend on other tasks, and it is done when it is checked off in the plan or when an agent completes it in Wake. The task&#39;s page in the web app shows its commits, verification and evidence.</p><h2 id="claim" tabindex="-1">Claim <a class="header-anchor" href="#claim" aria-label="Permalink to &quot;Claim&quot;">​</a></h2><p>An agent claims a task before it works on it, so two sessions never build the same thing. While the claim is active, only the session that holds it can change the task. A claim lasts 5 minutes unless the agent asks for longer (up to an hour), and the agent renews it while it works. A claim whose holder stopped renewing it is stale: another session takes the task over only after you confirm.</p><h2 id="session" tabindex="-1">Session <a class="header-anchor" href="#session" aria-label="Permalink to &quot;Session&quot;">​</a></h2><p>A session is one run of a coding agent in a connected repository, from the moment it opens until it closes. When it starts, Wake syncs the plan and tells the agent which tasks are free and which other sessions hold. Its claims, progress and tool calls are recorded under it, and when it ends Wake releases the claims it still holds.</p><h2 id="evidence" tabindex="-1">Evidence <a class="header-anchor" href="#evidence" aria-label="Permalink to &quot;Evidence&quot;">​</a></h2><p>Evidence is proof that a task&#39;s work is done: test output, screenshots, logs, a link or a short note. The agent attaches it before it completes the task, and Wake refuses to complete a task without evidence unless the agent states why none is possible; that reason is recorded with the task. Evidence files are kept in your installation&#39;s own storage (see <a href="/wake-dist/docs/run/evidence-storage">Evidence storage</a>).</p><h2 id="milestone" tabindex="-1">Milestone <a class="header-anchor" href="#milestone" aria-label="Permalink to &quot;Milestone&quot;">​</a></h2><p>A milestone groups phases under a goal, such as a first release. Milestones are optional: you list them in a milestones file in the repository, and the Roadmap shows them across the top. A milestone can name the version that delivers it. See <a href="/wake-dist/docs/agents/milestones">Milestones</a>.</p><h2 id="version" tabindex="-1">Version <a class="header-anchor" href="#version" aria-label="Permalink to &quot;Version&quot;">​</a></h2><p>A version is a git tag of your repository, such as <code>v1.0.0</code>. Wake reads your tags when it syncs: a version holds the tasks done in its tagged commit that no lower version already released. You never create versions in the web app. See <a href="/wake-dist/docs/use/versions">Versions and tags</a>.</p>',18)])])}const m=s(n,[["render",i]]);export{u as __pageData,m as default};
